import{_ as e,o,c as a,a2 as n}from"./chunks/framework.ChIlRNAd.js";const g=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/settings.md","filePath":"en/guide/settings.md"}'),s={name:"en/guide/settings.md"};function r(i,t,c,h,l,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Settings</strong> (<code>/settings/…</code>) is split into five sections, as tabs on desktop and listed in the <strong>More</strong> page on mobile:</p><table tabindex="0"><thead><tr><th>Section</th><th>Address</th></tr></thead><tbody><tr><td><a href="#account">Account</a></td><td><code>/settings/account</code></td></tr><tr><td><a href="#security">Security</a></td><td><code>/settings/security</code></td></tr><tr><td><a href="#gmail-accounts">Gmail accounts</a></td><td><code>/settings/gmail</code></td></tr><tr><td><a href="#notifications-webhooks">Notifications &amp; webhooks</a></td><td><code>/settings/notifications</code></td></tr><tr><td><a href="#data">Data</a></td><td><code>/settings/data</code></td></tr><tr><td><a href="#about">About</a></td><td><code>/settings/about</code></td></tr></tbody></table><hr><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><ul><li><strong>Profile</strong>: avatar, name, email, and the space used by your archives (&quot;Archives: X used of Y&quot;, quota set by the administrator).</li><li><strong>Language and appearance</strong>: <strong>Language</strong> (French / English) and <strong>Theme</strong> (<strong>System</strong>, <strong>Light</strong>, <strong>Dark</strong>). Language and dark mode are also in the avatar menu.</li><li><strong>Reading</strong>: <ul><li><strong>Show remote images</strong>: off by default, since these images are often used to know when you open a mail. A &quot;Show&quot; button stays available in each mail.</li><li><strong>Single-key keyboard shortcuts</strong>: turns on the <a href="./mails.html#keyboard-shortcuts">Mail shortcuts</a> (<code>j</code>/<code>k</code>, <code>e</code>, <code>#</code>, <code>r</code>, <code>u</code>, <code>/</code>). Turn off if you use voice control.</li></ul></li></ul><hr><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="password" tabindex="-1">Password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;Password&quot;">​</a></h3><p>Local accounts only (a Google or SSO account has no Nid password): <strong>Current password</strong>, <strong>New password</strong> (at least 8 characters) and its confirmation, then <strong>Change password</strong>. Your other open sessions are signed out.</p><p>Forgot your password: on the sign-in screen, <strong>Forgot your password?</strong> sends a link valid for 1 hour (when the instance has an SMTP server, see <a href="./../installation/configuration.html#e-mail-smtp">Configuration</a>). Otherwise, ask an administrator to reset it (<a href="./admin.html#users">Administration</a>).</p><h3 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h3><p>A passkey replaces both password and 2FA code: you sign in with your device&#39;s PIN or biometrics (Face ID, Windows Hello, fingerprint, security key). Give it a <strong>Name</strong> (e.g. &quot;iPhone&quot;), then <strong>Add a passkey</strong> and follow the browser&#39;s dialog. Then, on the sign-in screen: <strong>Sign in with a passkey</strong>, without typing an e-mail. The list shows when each passkey was last used; the bin icon removes it.</p><p>The card only shows when the browser supports passkeys. A passkey is bound to the instance&#39;s address: if that address changes, register new ones.</p><h3 id="two-factor-authentication-2fa" tabindex="-1">Two-factor authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-factor authentication (2FA)&quot;">​</a></h3><ol><li>Click <strong>Set up 2FA</strong></li><li>Scan the QR code with your authenticator app (Google Authenticator, Aegis, Authy…), or enter the key shown</li><li>Enter the <strong>6-digit code</strong> then <strong>Verify and turn on</strong></li></ol><p>Once on, a code is asked at each sign-in, including with Google or another provider (SSO). To turn it off, enter a code then <strong>Turn off 2FA</strong>.</p><h3 id="api-tokens" tabindex="-1">API tokens <a class="header-anchor" href="#api-tokens" aria-label="Permalink to &quot;API tokens&quot;">​</a></h3><p>For Home Assistant or a script. Give the token a <strong>Name</strong>, choose its <strong>Permissions</strong> (<em>Read only</em>, or <em>Read and actions</em> to start jobs or rules) and an <strong>Expiration</strong>, then <strong>Create token</strong>. Copy it right away: it is shown only once. Send it in the <code>Authorization: Bearer nid_…</code> header. A token never reaches account security, administration, encryption, webhooks or share links. The list shows when each token was last used; the bin icon revokes it. See the <a href="./../technical/api/auth.html#api-tokens">API reference</a>.</p><h3 id="share-links" tabindex="-1">Share links <a class="header-anchor" href="#share-links" aria-label="Permalink to &quot;Share links&quot;">​</a></h3><p>Number of active share links to your archived mails, with the <strong>Manage share links in Archives</strong> link (<a href="./archives.html#shares-tab">Shares</a> tab).</p><hr><h2 id="gmail-accounts" tabindex="-1">Gmail accounts <a class="header-anchor" href="#gmail-accounts" aria-label="Permalink to &quot;Gmail accounts&quot;">​</a></h2><p>Each connected account shows:</p><ul><li>its state: <strong>Synced</strong>, <strong>Action required</strong> (Google withdrew Nid&#39;s access: reconnect the account to resume sync and backups) or <strong>Disconnected</strong>;</li><li><strong>Sync</strong>: &quot;Last synced …&quot;, number of mails in Gmail, <strong>Sync now</strong> button;</li><li><strong>NAS backup</strong>: <strong>Automatic backup</strong> (saves the account&#39;s new mails to the NAS) and its <strong>Frequency</strong>: Every hour, Every 6 hours, Once a day;</li><li><strong>Reconnect with Google</strong> and <strong>Disconnect</strong>.</li></ul><p><strong>Disconnect</strong> asks for confirmation: Nid stops syncing and backing up this account, but its archives stay on the NAS and in Nid. Pages that need Gmail (Overview, Mail, Cleanup, Rules) then show &quot;… is disconnected&quot; with <strong>Reconnect in Settings</strong>; <a href="./archives.html">Archives</a> stays available.</p><p><strong>Add a Gmail account</strong> connects a new account, within the limit shown (&quot;N / max accounts&quot;). Requested access: <code>gmail.modify</code>, <code>gmail.labels</code>.</p><hr><h2 id="notifications-webhooks" tabindex="-1">Notifications &amp; webhooks <a class="header-anchor" href="#notifications-webhooks" aria-label="Permalink to &quot;Notifications &amp; webhooks&quot;">​</a></h2><p>Per-event preferences (in-app, toast) and webhooks to Discord, Slack, ntfy or your own URL: see <a href="./notifications.html">Notifications</a>.</p><hr><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>Imports and export apply to the active Gmail account.</p><h3 id="import-an-mbox-file" tabindex="-1">Import an mbox file <a class="header-anchor" href="#import-an-mbox-file" aria-label="Permalink to &quot;Import an mbox file&quot;">​</a></h3><p>A Google Takeout or other mail client export, added to the account&#39;s archives (Gmail labels kept). Click <strong>Choose an .mbox file</strong>; follow the import in <a href="./activity.html">Activity</a>.</p><div class="tip custom-block"><p class="custom-block-title">Google Takeout</p><ol><li>Go to <a href="https://takeout.google.com" target="_blank" rel="noreferrer">takeout.google.com</a></li><li>Select only <strong>Gmail</strong>, in <strong>mbox</strong> format</li><li>Download the archive and import the <code>.mbox</code> file into Nid</li></ol></div><h3 id="import-from-an-imap-server" tabindex="-1">Import from an IMAP server <a class="header-anchor" href="#import-from-an-imap-server" aria-label="Permalink to &quot;Import from an IMAP server&quot;">​</a></h3><p>Copies the mails of another mailbox (Outlook, Fastmail…) into the account&#39;s archives. Fields: <strong>Server</strong>, <strong>Port</strong>, <strong>Username</strong>, <strong>Password</strong>, <strong>Folder</strong>, <strong>Maximum number of mails</strong>, <strong>Encrypted connection (TLS)</strong>, then <strong>Start import</strong>. The password is not kept.</p><div class="warning custom-block"><p class="custom-block-title">App password</p><p>Many providers (Google, Outlook, Yahoo) require an <strong>app password</strong> rather than your usual password.</p></div><h3 id="export-archives" tabindex="-1">Export archives <a class="header-anchor" href="#export-archives" aria-label="Permalink to &quot;Export archives&quot;">​</a></h3><p><strong>Export (.mbox)</strong>: all of the account&#39;s archives in an .mbox file, readable by Thunderbird or Apple Mail.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Your rules and webhooks in a JSON file, to back them up or move them to another instance: <strong>Export configuration</strong> / <strong>Import a configuration</strong>.</p><h3 id="my-data-gdpr" tabindex="-1">My data (GDPR) <a class="header-anchor" href="#my-data-gdpr" aria-label="Permalink to &quot;My data (GDPR)&quot;">​</a></h3><p><strong>Export my data</strong>: everything Nid stores about you in a JSON file (profile, Gmail accounts, rules, archive metadata, activity log…). Mail content is exported as .mbox (above); secrets (passwords, tokens) are left out.</p><h3 id="delete-my-account" tabindex="-1">Delete my account <a class="header-anchor" href="#delete-my-account" aria-label="Permalink to &quot;Delete my account&quot;">​</a></h3><p>Type your password (or, for a Google/SSO account, your e-mail address), then <strong>Permanently delete my account</strong> and confirm. Your account, connected Gmail accounts, archives and rules are deleted from Nid; nothing is deleted in Gmail. The instance&#39;s last administrator cannot delete their account.</p><hr><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><ul><li><strong>Version</strong>: the installed Nid version, and whether a newer one is published (checked twice a day, with the time of the last check). When an update exists, the card links to what&#39;s new and gives the command to run.</li><li><strong>What Nid talks to</strong>: the external services the instance talks to (Google, ghcr.io for the version check, your SMTP, your webhooks, the configured SSO providers). No telemetry.</li><li><strong>Project</strong>: MIT licence, source code, release history, reporting a problem.</li></ul>',50)])])}const m=e(s,[["render",r]]);export{g as __pageData,m as default};
